/* Generated by tools/build.js from data/rhcsa.js. Edit that file, not this one. */
CertHub.addQuestions("rhcsa", [["rh1",0,1,"An admin runs a script and wants both normal output and error messages appended to /var/log/job.log without overwriting it. Which redirection is correct?",["job.sh > /var/log/job.log 2>&1","job.sh | tee /var/log/job.log","job.sh 2>&1 >> /var/log/job.log","job.sh >> /var/log/job.log 2>&1"],3,">> appends stdout, and 2>&1 afterwards sends stderr to the same place. Putting 2>&1 first copies stderr to the terminal before stdout moves; a single > overwrites the file.","Essential tools: I/O redirection",["A single > truncates the log every run, so earlier entries are lost even though stderr is captured.","tee without -a overwrites the file, and the pipe only carries stdout, so error messages still go to the terminal.","Redirections are processed left to right: 2>&1 first copies stderr to the terminal, then only stdout is moved to the file.",null],null],["rh2",0,1,"Which command lists every line in /etc/passwd that ends with the string nologin?",["grep '^nologin' /etc/passwd","grep -v 'nologin' /etc/passwd","grep 'nologin$' /etc/passwd","grep -c 'nologin' /etc/passwd"],2,"$ anchors the match to the end of the line. ^ anchors to the start, -v inverts the match and -c only counts lines.","Essential tools: grep and regular expressions",["^ anchors the pattern to the start of the line, so this only matches lines beginning with nologin (none in /etc/passwd).","-v inverts the match and prints every line that does NOT contain nologin, the opposite of what is asked.",null,"-c prints only a count of matching lines, not the lines themselves, and it doesn't anchor to the end of the line."],null],["rh3",0,1,"You need a compressed archive of /etc called /root/etc.tar.bz2. Which command creates it?",["tar -czf /root/etc.tar.bz2 /etc","tar -xjf /root/etc.tar.bz2 /etc","tar -cJf /root/etc.tar.bz2 /etc","tar -cjf /root/etc.tar.bz2 /etc"],3,"-c creates, -j uses bzip2 and -f names the file. -z would use gzip and -J xz, so the extension would be wrong; -x extracts.","Essential tools: archive and compress with tar and bzip2",["-z compresses with gzip, so the file would be a .tar.gz stream despite the .bz2 name.","-x extracts an existing archive instead of creating one; it would fail because the archive doesn't exist yet.","-J (capital) uses xz compression, so the content would not match the .bz2 extension.",null],null],["rh4",0,1,"A user deletes /data/report.txt. A link that pointed to it still shows the old contents. What kind of link was it?",["An autofs map entry","A symbolic link to the path","A bind mount of the directory","A hard link to the same inode"],3,"A hard link is a second name for the same inode, so the data remains until the last hard link is removed. A symbolic link stores the path and would be broken.","Essential tools: hard and soft links",["autofs mounts file systems on demand; it isn't a file link and has nothing to do with a deleted file still being readable.","A symbolic link stores the path, so once report.txt is deleted the symlink dangles and shows an error, not the old contents.","A bind mount shows a directory tree at a second location; deleting the file in one place removes it from both views.",null],null],["rh5",0,1,"Which command creates a symbolic link /usr/local/bin/backup that points to /opt/tools/backup.sh?",["ln /opt/tools/backup.sh /usr/local/bin/backup","cp -s /usr/local/bin/backup /opt/tools/backup.sh","ln -s /usr/local/bin/backup /opt/tools/backup.sh","ln -s /opt/tools/backup.sh /usr/local/bin/backup"],3,"ln -s TARGET LINKNAME: the existing file comes first and the new link name second. Without -s, ln makes a hard link.","Essential tools: hard and soft links",["Without -s, ln creates a hard link, not a symbolic link, and hard links can't point across file systems.","cp -s makes symlinks while copying, and here the arguments are reversed, so it would try to use the nonexistent link as the source.","The arguments are backwards: this would try to create a link named /opt/tools/backup.sh pointing at /usr/local/bin/backup.",null],null],["rh6",0,1,"A file must be readable and writable by its owner, readable by its group and give no access to others. Which numeric mode is correct?",["644","660","640","604"],2,"Owner rw = 6, group r = 4, others none = 0, giving 640. 644 would let others read the file.","Essential tools: list, set and change ugo/rwx permissions",["644 gives others read (4), but the requirement is no access at all for others.","660 gives the group write permission too, while the group should only read.",null,"604 gives the group no access and lets others read, which is the reverse of what's needed."],null],["rh7",0,1,"An admin wants to add execute permission for the group only on deploy.sh, without changing any other bits. Which command does this?",["chmod 710 deploy.sh","chmod g=x deploy.sh","chmod +x deploy.sh","chmod g+x deploy.sh"],3,"g+x adds execute for the group and leaves the rest alone. g=x would remove the group's read/write, +x adds execute for everyone, and 710 replaces every bit.","Essential tools: list, set and change ugo/rwx permissions",["710 replaces every bit, removing the owner's read/write settings and everything the group and others had, not just adding group execute.","g=x sets the group to execute only, removing any read or write the group already had.","+x with no class adds execute for user, group and others (subject to umask), not just the group.",null],null],["rh8",0,1,"You need to edit /etc/fstab but can't remember the meaning of its fields. Which command opens the documentation for the file format?",["whatis -f fstab","man 8 fstab","info mount -k","man 5 fstab"],3,"Section 5 of the manual covers file formats. Section 8 holds admin commands such as mount.","Essential tools: locate and use system documentation",["whatis prints only a one-line description of a page; it doesn't open the documentation, and -f just means 'look up by name'.","Section 8 covers administration commands such as mount; there is no fstab page there, so man 8 fstab finds nothing.","info mount opens the mount command's documentation, not the fstab file format, and -k is not how info searches.",null],null],["rh9",0,1,"`man -k partition` returns 'nothing appropriate' on a fresh system. What should you run first?",["updatedb","restorecon -R /usr/share/man","dnf reinstall man","mandb"],3,"man -k searches the whatis database, which mandb builds. updatedb builds the locate database, not the man index.","Essential tools: locate and use system documentation",["updatedb builds the database for locate/plocate, not the whatis index that man -k searches.","restorecon resets SELinux labels; labels are not why the man keyword index is empty.","Reinstalling man doesn't necessarily build the index; the whatis database is generated by mandb.",null],null],["rh10",0,1,"You are logged in as a normal user and need a full root login environment with root's PATH and home directory. Which command is best?",["su root","sudo -s","su -","sudo su"],2,"su - (or su -l) starts a login shell as root, loading root's environment. Plain su keeps much of the current user's environment.","Essential tools: log in and switch users",["Plain su root starts a non-login shell that keeps most of the current user's environment, such as PATH and the working directory.","sudo -s starts a root shell but not a login shell, so root's login environment and home directory aren't fully loaded.",null,"sudo su runs plain su, which gives a non-login shell; it would need sudo su - or sudo -i to load root's full environment."],null],["rh11",0,1,"Which command copies the /srv/site directory tree to /backup while keeping permissions, ownership and timestamps?",["cp -i /srv/site /backup/","cp -r /srv/site /backup/","mv -f /srv/site /backup/","cp -a /srv/site /backup/"],3,"-a (archive) copies recursively and keeps modes, ownership, timestamps and links. -r copies recursively but not all attributes; mv moves the data instead of copying it.","Essential tools: create, delete, copy and move files",["-i only prompts before overwriting; without -r it won't even copy a directory, and it doesn't preserve attributes.","-r copies recursively but ownership and timestamps are reset to the copying user and current time.","mv moves the tree instead of copying it, so /srv/site would no longer exist in its original place.",null],null],["rh12",0,2,"A task says to use the repository at http://repo.example.com/BaseOS. Which line in the .repo file points dnf at it?",["mirrorlist=http://repo.example.com/BaseOS","url=http://repo.example.com/BaseOS","baseurl=http://repo.example.com/BaseOS","source=http://repo.example.com/BaseOS"],2,"baseurl= gives the location of the repository metadata. mirrorlist points to a list of mirrors, and url= and source= are not repo keys.","Manage software: configure access to RPM repositories",["mirrorlist= points to a file that lists mirrors, not directly at a repository's metadata.","url= is not a valid key in a dnf .repo section, so dnf ignores it and the repo has no location.",null,"source= is not a .repo option; dnf would not know where the repository is."],null],["rh13",0,2,"The semanage command is missing on a minimal system. Which command tells you which package provides it?",["rpm -qf semanage","dnf provides '*/semanage'","dnf info semanage","rpm -ql semanage"],1,"dnf provides searches repository metadata for the package that owns a file. rpm -qf only works for files already installed.","Manage software: install and remove RPM packages",["rpm -qf only maps a file that already exists on disk to its package, and it needs a path; it can't search for missing commands.",null,"dnf info needs a package name, and semanage is a command, not a package name, so it won't reveal the providing package.","rpm -ql lists files of an installed package named semanage; there is no such installed package."],null],["rh14",0,2,"Which command shows the configuration files that belong to the installed openssh-server package?",["rpm -qa openssh-server","rpm -qi openssh-server","dnf list openssh-server","rpm -qc openssh-server"],3,"-qc lists the package's config files. -qi shows package info, -qa lists installed packages and dnf list shows versions.","Manage software: install and remove RPM packages",["rpm -qa lists installed packages matching the name; it doesn't show which files belong to the package.","rpm -qi prints package details such as version, vendor and description, not its config files.","dnf list shows installed and available versions of the package, not its files.",null],null],["rh15",0,2,"You must make Flathub available as a Flatpak source without an error if it already exists. Which command fits?",["flatpak install flathub --system","flatpak remote-add --if-not-exists flathub https://dl.flathub.org/repo/flathub.flatpakrepo","dnf config-manager --add-repo https://dl.flathub.org/repo/","flatpak remote-modify --enable flathub"],1,"flatpak remote-add creates a remote; --if-not-exists stops it from failing when the remote already exists. dnf config-manager adds RPM repos, not Flatpak remotes.","Manage software: configure access to Flatpak repositories",["flatpak install installs an application; it needs an existing remote and doesn't add Flathub as a source.",null,"dnf config-manager --add-repo adds RPM repositories for dnf; Flatpak doesn't read dnf repo files.","remote-modify only changes a remote that already exists; it fails if Flathub was never added."],null],["rh16",0,2,"Which command lists the Flatpak applications installed on the system?",["flatpak remotes","flatpak search --installed","flatpak list --app","dnf list installed flatpak"],2,"flatpak list shows installed refs, and --app filters out runtimes. flatpak remotes lists sources, and dnf only knows about RPMs.","Manage software: install and remove Flatpak packages",["flatpak remotes lists the configured sources (remotes), not the applications installed from them.","flatpak search looks up applications in remote metadata; --installed is not an option for it.",null,"dnf only tracks RPM packages, so this shows at most the flatpak package itself, not Flatpak apps."],null],["rh17",0,2,"A package update last week broke an application. Which approach reverts that transaction?",["dnf downgrade --all","rpm -e --nodeps on each package","dnf clean all then reboot","dnf history undo with the transaction ID"],3,"dnf history lists transactions and dnf history undo <ID> reverses one. dnf clean all only removes cached metadata.","Manage software: install and remove RPM packages",["dnf downgrade --all isn't a valid transaction revert; downgrade works on named packages and wouldn't target just last week's changes.","rpm -e --nodeps removes packages while ignoring dependencies, which can break the system further instead of restoring old versions.","dnf clean all only deletes cached metadata and packages; rebooting doesn't change installed versions.",null],null],["rh18",0,3,"In a script, which test is true when /etc/app.conf exists and is a regular file?",["[ -d /etc/app.conf ]","[ -z /etc/app.conf ]","[ -x /etc/app.conf ]","[ -f /etc/app.conf ]"],3,"-f tests for a regular file. -d is for directories, -z tests for an empty string and -x for execute permission.","Shell scripts: conditionally execute code",["-d tests whether the path is a directory, so it's false for a regular config file.","-z tests whether a string is empty; the literal path string is never empty, so this is always false and never checks the file.","-x tests for execute permission, which a config file usually doesn't have, and it doesn't confirm it's a regular file.",null],null],["rh19",0,3,"A script must print a usage message when it is run with no arguments. Which condition detects that case?",["if [ $@ -eq 1 ]; then","if [ $0 -eq 0 ]; then","if [ $? -eq 0 ]; then","if [ $# -eq 0 ]; then"],3,"$# is the number of arguments. $0 is the script's name and $? the previous command's exit status.","Shell scripts: process script inputs",["$@ expands to all arguments as words, not a count, so the numeric test fails or errors.","$0 is the script's name, a string, so comparing it numerically to 0 produces an error.","$? is the exit status of the previous command, which has nothing to do with how many arguments were passed.",null],null],["rh20",0,3,"Which loop runs a command once for every line in /root/hosts.txt, keeping spaces within each line?",["for h in /root/hosts.txt; do","while read -r h; do ... done < /root/hosts.txt","for h in $(ls /root/hosts.txt); do","until read h; do ... done > /root/hosts.txt"],1,"while read -r with input redirected from the file reads one full line at a time. The first for loop iterates once over the filename itself.","Shell scripts: use looping constructs",["This loops once over the literal word /root/hosts.txt, not over the file's lines.",null,"$(ls /root/hosts.txt) just outputs the filename, so the loop runs once over the name, not the contents.","until loops while the command fails, and > would redirect output into the file and truncate it rather than read from it."],null],["rh21",0,3,"Which line stores the number of lines containing 'bash' in /etc/passwd in the variable n?",["$n=$(grep -c bash /etc/passwd)","n='grep -c bash /etc/passwd'","n=grep -c bash /etc/passwd","n=$(grep -c bash /etc/passwd)"],3,"$( ) runs the command and substitutes its output. Single quotes store the literal text; $n= is not valid assignment syntax.","Shell scripts: process output of shell commands",["Assignments don't use $ on the left; $n=... expands n and tries to run the result as a command.","Single quotes store the literal text of the command in n; nothing is executed or counted.","Without $( ), the shell treats n=grep as a temporary variable for the command -c, which fails; n is never set to a count.",null],null],["rh22",0,3,"After running `grep -q root /etc/shadow`, a script checks `$?`. What does a value of 0 mean?",["The command was not found","The file could not be read","A match was found","No match was found"],2,"Exit status 0 means success, and for grep that means a match. grep returns 1 for no match and 2 for errors.","Shell scripts: conditionally execute code",["Command not found gives exit status 127, not 0.","An unreadable file makes grep exit with status 2 (error), not 0.",null,"grep exits with 1 when no line matches; 0 means at least one match."],null],["rh23",0,3,"A script at /root/scripts/check.sh starts with #!/bin/bash but `./check.sh` returns 'Permission denied'. What is the fix?",["Add the directory to PATH","chmod +x /root/scripts/check.sh","Change the shebang to #!/bin/sh","Run restorecon on the script"],1,"Running a script by path needs execute permission. PATH only matters when you type the name without a path.","Shell scripts: create simple shell scripts",["PATH only matters when a command is typed without a path; ./check.sh already gives the path, and the error is about permission.",null,"The interpreter is fine; changing to /bin/sh doesn't add the execute bit the kernel needs to run the file.","restorecon fixes SELinux labels; the 'Permission denied' here comes from the missing execute bit on a script in root's home."],null],["rh24",0,4,"You need to reset a lost root password on RHEL 10. At the GRUB menu, what do you add to the kernel line?",["single","init=/sbin/nologin","systemd.unit=multi-user.target","rd.break"],3,"rd.break stops boot in the initramfs, where you remount /sysroot read-write, chroot and run passwd. multi-user.target is a normal boot.","Operate running systems: interrupt the boot process to gain access",["single boots into rescue mode, which on RHEL still asks for the root password, so it doesn't help when the password is lost.","init=/sbin/nologin would make the kernel run nologin as PID 1, which just exits and causes a kernel panic.","multi-user.target is the normal non-graphical boot target, which ends at a login prompt that needs the password.",null],null],["rh25",0,4,"After changing the root password from the rd.break shell, why do you run `touch /.autorelabel` before rebooting?",["It forces fsck on the root file system","It makes SELinux relabel files, fixing /etc/shadow's context","It rebuilds the initramfs for the new password","It clears the systemd journal"],1,"passwd in the chroot creates /etc/shadow with the wrong SELinux label. The autorelabel flag makes SELinux relabel the file system on the next boot so logins work.","Operate running systems: interrupt the boot process to gain access",["fsck is not triggered by /.autorelabel; that file is only read by SELinux at boot.",null,"The password is in /etc/shadow on disk, not in the initramfs, so nothing needs rebuilding and the flag doesn't do that.","Clearing the journal has nothing to do with the password reset; /.autorelabel triggers an SELinux relabel."],null],["rh26",0,4,"A server is slow. Which command lists processes sorted by CPU use, highest first?",["ps aux --sort=-%cpu","ps -ef --sort=pid","pgrep -l cpu","top -b -n 1 -o PID | head"],0,"ps aux --sort=-%cpu sorts by CPU descending (the minus sign reverses the order). Sorting by pid doesn't show the heavy processes first.","Operate running systems: identify CPU and memory intensive processes",[null,"--sort=pid orders processes by ID, so heavy CPU users are not listed first.","pgrep -l cpu finds processes whose name matches 'cpu'; it doesn't measure or sort by CPU usage.","-o PID sorts top's output by process ID rather than %CPU, so the busiest processes aren't guaranteed at the top."],null],["rh27",0,4,"A process with PID 4120 ignores `kill 4120`. Which command ends it without giving it a chance to clean up?",["kill -1 4120","kill -15 4120","kill -9 4120","kill -18 4120"],2,"Signal 9 (SIGKILL) cannot be caught or ignored. 15 is SIGTERM, which is what plain kill already sent; 1 is SIGHUP and 18 is SIGCONT.","Operate running systems: kill processes",["Signal 1 (SIGHUP) usually tells a daemon to reload, and it can be caught or ignored just like SIGTERM.","Signal 15 (SIGTERM) is what plain kill already sent; the process ignored it, so sending it again won't help.",null,"Signal 18 (SIGCONT) resumes a stopped process; it doesn't terminate anything."],null],["rh28",0,4,"A backup job with PID 2250 should use less CPU than other processes. Which command gives it the lowest scheduling priority?",["renice -n -20 -p 2250","nice -n 19 2250","renice -n 19 -p 2250","kill -STOP 2250"],2,"A nice value of 19 is the lowest priority, and renice changes a running process. -20 is the highest priority; nice only starts new commands.","Operate running systems: adjust process scheduling",["-20 is the highest priority, so this would give the backup more CPU, not less (and only root can set it).","nice starts a new command with a niceness; it can't change an existing PID and would try to run a program called 2250.",null,"SIGSTOP pauses the process entirely rather than lowering its priority, so the backup would stop making progress."],null],["rh29",0,4,"Which command applies the tuning profile that tuned suggests for the current system?",["tuned-adm profile $(tuned-adm recommend)","tuned-adm active","systemctl set-default tuned","tuned-adm profile --recommended --apply-now"],0,"tuned-adm recommend prints the suggested profile, and tuned-adm profile applies it. tuned-adm active only shows the current profile.","Operate running systems: manage tuning profiles",[null,"tuned-adm active only reports which profile is currently in use; it changes nothing.","systemctl set-default sets the default boot target; tuned is not a target, and this doesn't apply a tuning profile.","tuned-adm profile has no --recommended or --apply-now options; the recommended profile comes from tuned-adm recommend."],null],["rh30",0,4,"After a reboot, `journalctl -b -1` says there are no earlier boots. What change makes journal entries survive reboots?",["Set Storage=persistent in journald.conf and restart systemd-journald","Enable the rsyslog service","Set SystemMaxUse=0 in journald.conf","Run logrotate -f /etc/logrotate.conf"],0,"By default the journal lives in /run and is lost at reboot unless /var/log/journal exists. Storage=persistent creates and uses it. rsyslog writes text logs but does not keep the journal.","Operate running systems: preserve system journals",[null,"rsyslog writes text log files such as /var/log/messages, but it doesn't make the systemd journal keep past boots.","SystemMaxUse limits how much disk the persistent journal can use; it doesn't switch storage from /run to /var/log/journal.","logrotate rotates text log files; it has no effect on whether the journal survives a reboot."],null],["rh31",0,4,"Which command shows only error-level and more severe messages logged by the sshd service since this morning at 08:00?",["journalctl -p err -u sshd --since 08:00","journalctl -f -u sshd --until 08:00","journalctl -k -p err --since 08:00","grep err /var/log/sshd --since 08:00"],0,"-p err filters by priority, -u selects the unit and --since limits the time. -k shows only kernel messages; there is no /var/log/sshd by default.","Operate running systems: locate and interpret system log files and journals",[null,"-f follows new messages live and --until 08:00 shows messages BEFORE 08:00, and there's no priority filter.","-k limits output to kernel messages, so sshd's own log entries are excluded.","RHEL has no /var/log/sshd by default, and grep has no --since option."],null],["rh32",0,4,"Failed su and ssh login attempts on RHEL are written to which text log file by default?",["/var/log/messages","/var/log/audit/audit.log","/var/log/boot.log","/var/log/secure"],3,"rsyslog writes authentication and authorization messages (authpriv) to /var/log/secure. /var/log/messages holds general messages.","Operate running systems: locate and interpret system log files",["/var/log/messages collects general system messages; authpriv messages are specifically excluded from it in rsyslog.conf.","audit.log is written by auditd and holds audit events such as SELinux AVCs in its own format; it isn't rsyslog's authentication log.","/var/log/boot.log holds service start-up messages from boot, not login attempts.",null],null],["rh33",0,4,"You must copy /etc/hosts to /tmp on server2 over an encrypted connection. Which command works?",["scp /etc/hosts server2:/tmp/","cp /etc/hosts server2:/tmp/","ssh server2 cp /etc/hosts /tmp/","sftp /etc/hosts server2:/tmp/"],0,"scp copies files over SSH. The ssh command would copy server2's own /etc/hosts, and sftp takes a host, not a source file, as its argument.","Operate running systems: securely transfer files between systems",[null,"cp only copies on the local system; it would treat 'server2:/tmp/' as a local path and fail.","This runs cp on server2, copying server2's own /etc/hosts to its /tmp; the local file never leaves this machine.","sftp takes a host to connect to and then uses interactive (or batch) put commands; it doesn't accept a local file followed by a destination like scp."],null],["rh34",0,4,"A system won't finish booting because of a bad fstab entry. Which kernel argument boots to a minimal root shell with the root file system mounted read-only?",["systemd.unit=graphical.target","systemd.unit=emergency.target","systemd.unit=multi-user.target","systemd.unit=default.target"],1,"emergency.target gives a root shell with / mounted read-only and few services. The others try to start the full system and hit the same fstab error.","Operate running systems: boot systems into different targets manually",["graphical.target is the full desktop boot, which still processes fstab and hits the same error.",null,"multi-user.target is a normal full boot without a GUI, so the bad fstab entry still blocks it.","default.target is just an alias for the normal boot target, so the same failing mount is attempted."],null],["rh35",0,5,"A new blank disk /dev/vdb needs a GPT partition table. Which command creates one?",["parted /dev/vdb mklabel gpt","mkfs.gpt /dev/vdb","fdisk -t gpt /dev/vdb1","pvcreate --gpt /dev/vdb"],0,"parted mklabel gpt writes a new GPT partition table. mkfs.gpt doesn't exist, and pvcreate prepares LVM physical volumes.","Configure local storage: list, create and delete partitions on GPT disks",[null,"There is no mkfs.gpt command; mkfs tools create file systems, not partition tables.","fdisk has no -t gpt option for creating a label, and /dev/vdb1 is a partition that doesn't exist yet on a blank disk.","pvcreate writes an LVM physical volume header and has no --gpt option; it doesn't create partition tables."],null],["rh36",0,5,"You created /dev/vdb1 for LVM. Which command must come before vgcreate can use it?",["lvcreate /dev/vdb1","mkfs.xfs /dev/vdb1","pvcreate /dev/vdb1","vgextend /dev/vdb1"],2,"pvcreate writes the LVM physical volume header. vgextend adds a PV to an existing VG, and mkfs would put a file system on it.","Configure local storage: create and remove physical volumes",["lvcreate carves logical volumes out of an existing volume group; it can't use a raw partition directly.","mkfs.xfs puts a file system on the partition, which LVM can't then use as a physical volume.",null,"vgextend adds an already-initialized PV to an existing VG and needs the VG name; it doesn't prepare the partition."],null],["rh37",0,5,"A task asks for volume group vgapp with a physical extent size of 16 MiB on /dev/vdb1. Which command is right?",["vgcreate -l 16M vgapp /dev/vdb1","vgcreate -s 16M vgapp /dev/vdb1","vgcreate vgapp /dev/vdb1 -L 16M","vgcreate --extents 16 vgapp /dev/vdb1"],1,"-s sets the physical extent size when the VG is created. -l and -L are lvcreate options for extents and size.","Configure local storage: assign physical volumes to volume groups",["-l is not the extent-size option for vgcreate (for lvcreate it means extent count), so this doesn't set 16 MiB extents.",null,"-L is an lvcreate size option; vgcreate doesn't accept it for extent size.","vgcreate has no --extents 16 option; the extent size is set with -s (--physicalextentsize)."],null],["rh38",0,5,"Volume group vgapp has 16 MiB extents. A task asks for logical volume lvlog made of exactly 40 extents. Which command creates it?",["lvcreate -L 40 -n lvlog vgapp","lvcreate -L 640M lvlog vgapp","lvcreate -s 40 -n lvlog vgapp","lvcreate -l 40 -n lvlog vgapp"],3,"-l takes a count of extents. -L 40 would mean 40 MiB, and -s creates a snapshot.","Configure local storage: create and delete logical volumes",["-L 40 means a size of 40 MiB (about 3 extents), not 40 extents.","-L 640M is the right size, but it's missing -n, so lvlog is read as the VG name and the command fails.","-s creates a snapshot volume in lvcreate, not an extent count.",null],null],["rh39",0,5,"Which /etc/fstab entry mounts an XFS file system by UUID on /data at boot?",["UUID=4f1c...e2 /data xfs defaults 0 0","/data UUID=4f1c...e2 xfs defaults 0 0","UUID=4f1c...e2 xfs /data defaults 0 0","UUID=4f1c...e2 /data defaults xfs 0 0"],0,"The field order is device, mount point, type, options, dump, fsck. The other entries put fields in the wrong order.","Configure local storage: mount file systems at boot by UUID or label",[null,"The mount point is in the device field and the UUID in the mount-point field; the first field must be the device.","The type and mount point are swapped, so mount would try to use 'xfs' as the mount point.","The options and type fields are swapped, so 'defaults' would be read as a file system type."],null],["rh40",0,5,"Which command shows the UUID and file system type of /dev/vdb1?",["pvs /dev/vdb1","df -T /dev/vdb1","fdisk -u /dev/vdb1","blkid /dev/vdb1"],3,"blkid reads the UUID, label and type from the device. df only works on mounted file systems and doesn't show UUIDs.","Configure local storage: mount file systems at boot by UUID or label",["pvs reports LVM physical volume details such as VG, size and free space, not the file system UUID and type.","df -T shows the type only for a mounted file system, and it never shows UUIDs.","fdisk -u sets display units; it doesn't read the file system UUID from a partition.",null],null],["rh41",0,5,"You created a new swap partition /dev/vdb2 and added it to fstab. Which commands prepare and activate it?",["mkfs.swap /dev/vdb2; mount -a","swapon /dev/vdb2; mkswap -a","mkswap /dev/vdb2; swapon -a","mkswap -a; swapon /dev/vdb2 -p"],2,"mkswap writes the swap signature, then swapon -a activates every swap entry in fstab. Swap is not mounted with mount.","Configure local storage: add swap non-destructively",["There is no mkfs.swap (the tool is mkswap), and swap is activated with swapon, not mount.","swapon fails before the swap signature exists, and mkswap has no -a option.",null,"mkswap needs a device and has no -a option; -p sets a priority but can't activate an unformatted partition."],null],["rh42",0,5,"Which fstab line makes a swap partition persistent?",["UUID=9ab2...77 /swap swap defaults 0 0","UUID=9ab2...77 none swap defaults 0 0","UUID=9ab2...77 swap none defaults 0 0","UUID=9ab2...77 none swap defaults 0 2"],1,"Swap uses none (or swap) as the mount point field, swap as the type, and 0 for fsck. A mount point like /swap, a swapped field order or an fsck pass of 2 are wrong.","Configure local storage: add swap non-destructively",["Swap is not mounted, so a directory like /swap as the mount point is wrong; use none or swap.",null,"The mount point and type fields are swapped, so the type would be read as 'none'.","The fsck pass must be 0 for swap; 2 would ask fsck to check a device with no file system."],null],["rh43",0,5,"A disk already has two partitions holding data. You must add a third partition without disturbing them. What is the safest approach?",["Run parted mklabel gpt and recreate all three","Use mkpart in the free space, then run partprobe or udevadm settle","Run wipefs on the disk and repartition","Delete partition 2 and resize it to fit the new one"],1,"Creating a partition only in unused space leaves the existing ones untouched; partprobe makes the kernel see it. mklabel and wipefs destroy the existing table.","Configure local storage: add new partitions non-destructively",["mklabel gpt writes a new empty partition table, which destroys the existing partitions and their data.",null,"wipefs erases partition-table and file-system signatures, which destroys the existing layout.","Deleting and resizing partition 2 risks its data and isn't needed when free space is available."],null],["rh44",0,5,"Which command shows all block devices, their sizes and mount points as a tree, including LVM volumes?",["lsblk","pvdisplay","mount -l","fdisk -s"],0,"lsblk shows disks, partitions and the LVs on them with sizes and mount points. pvdisplay only shows physical volumes.","Configure local storage: list partitions",[null,"pvdisplay shows only LVM physical volume details, not every disk, partition and mount point as a tree.","mount -l lists mounted file systems, not unmounted disks or a device tree with sizes.","fdisk -s prints the size of a single device in blocks; it doesn't show a tree or mount points."],null],["rh45",0,5,"An unused logical volume /dev/vgapp/lvold must be removed. Which command does it?",["vgreduce vgapp lvold","lvreduce -L 0 /dev/vgapp/lvold","pvremove /dev/vgapp/lvold","lvremove /dev/vgapp/lvold"],3,"lvremove deletes a logical volume (unmount it and remove its fstab entry first). vgreduce removes a PV from a VG and pvremove wipes a PV label.","Configure local storage: create and delete logical volumes",["vgreduce removes a physical volume from a volume group; it doesn't delete a logical volume.","lvreduce can't shrink a volume to 0 and wouldn't delete it; the LV would still exist.","pvremove wipes the label from a physical volume, not a logical volume path.",null],null],["rh46",0,6,"A USB stick image must use a file system that Windows can also read. Which command creates it on /dev/vdc1?",["mkfs.xfs /dev/vdc1","mkfs.ext4 /dev/vdc1","mkfs.vfat /dev/vdc1","mkswap /dev/vdc1"],2,"vfat (FAT32) is readable by Windows, macOS and Linux. XFS and ext4 are Linux file systems.","File systems: create, mount and use vfat, ext4 and xfs",["XFS is a Linux file system that Windows can't read without extra software.","ext4 is a Linux file system that Windows doesn't read natively.",null,"mkswap creates swap space, which isn't a file system for storing files."],null],["rh47",0,6,"The XFS logical volume /dev/vgdata/lvweb is mounted and needs 500 MiB more space. Which single command grows the LV and its file system?",["lvextend -r -L +500M /dev/vgdata/lvweb","lvresize -L 500M /dev/vgdata/lvweb","xfs_growfs -L +500M /dev/vgdata/lvweb","resize2fs /dev/vgdata/lvweb 500M"],0,"-r resizes the file system after extending the LV. -L 500M (no +) sets an absolute size, which could shrink it; resize2fs is for ext4.","File systems: extend existing logical volumes",[null,"Without + this sets the LV to exactly 500 MiB (possibly shrinking it), and without -r the file system isn't grown.","xfs_growfs grows the file system to fill its device but has no way to add space to the LV, and -L isn't its size option.","resize2fs is for ext2/3/4, not XFS, and 500M would be an absolute size."],null],["rh48",0,6,"You need to make an XFS file system smaller. What is true?",["xfs_growfs can shrink it if it is unmounted","XFS cannot be shrunk; back up, recreate and restore","lvreduce -r shrinks XFS safely online","xfs_repair -L shrinks it to the LV size"],1,"XFS can only grow. To make it smaller you must back up the data, create a smaller file system and restore. ext4 can shrink when unmounted.","File systems: extend existing logical volumes",["xfs_growfs can only grow a file system, mounted or not; XFS has no shrink operation.",null,"lvreduce -r calls fsadm, which can't shrink XFS, so the command fails (or risks data if forced without -r).","xfs_repair checks and repairs metadata; -L zeroes the log and doesn't resize anything."],null],["rh49",0,6,"Which fstab entry mounts the NFS export nfs1:/exports/share on /mnt/share at boot, waiting for the network first?",["nfs1:/exports/share /mnt/share xfs defaults 0 0","/mnt/share nfs1:/exports/share nfs defaults 0 0","nfs1:/exports/share /mnt/share nfs defaults,_netdev 0 0","nfs1:/exports/share /mnt/share nfs defaults 0 1"],2,"The type is nfs, _netdev marks it as needing the network, and network file systems get 0 for fsck. The other lines have the wrong type, field order or fsck value.","File systems: mount and unmount network file systems using NFS",["The type is xfs, but an NFS export must use type nfs, and there's no _netdev option.","The mount point and the export are swapped; the first field must be the NFS source.",null,"fsck pass 1 is wrong for a network file system, and without _netdev it isn't marked as needing the network."],null],["rh50",0,6,"You need home directories from nfs1:/home/<user> to mount on demand under /rhome/<user>. In /etc/auto.master.d/rhome.autofs you point /rhome at /etc/auto.rhome. What goes in /etc/auto.rhome?",["* -rw,sync nfs1:/home/&","& -rw,sync nfs1:/home/*","/rhome/* nfs1:/home/* nfs rw","* nfs1:/home -rw,sync"],0,"In an indirect map, * matches any key accessed under /rhome and & repeats that key in the server path. The options come between the key and the location.","File systems: configure autofs",[null,"The wildcards are reversed: & must be in the location, and * must be the key.","In an indirect map the key is relative to /rhome, not a full path, and nfs1:/home/* doesn't substitute the key; & does.","Options must come before the location, and the location lacks & so every key would mount the whole /home."],null],["rh51",0,6,"You edited autofs map files but /rhome/alice still doesn't mount. autofs is running. What should you do next?",["Run mount -a","Run exportfs -r on the client","Restart autofs with systemctl","Add the path to /etc/fstab"],2,"autofs reads the master map at start, so restart or reload it after changes. mount -a only uses fstab, and exportfs runs on the NFS server.","File systems: configure autofs",["mount -a only processes /etc/fstab; autofs maps aren't read by it.","exportfs -r refreshes the export table on the NFS server, not on the autofs client.",null,"Adding it to fstab creates a static mount and bypasses autofs, which the task requires to mount on demand."],null],["rh52",0,6,"A user can't read /projects/team/plan.txt even though the file is mode 644. What is the most likely cause?",["The file needs the sticky bit","The user's umask is too strict","A parent directory lacks execute permission for the user","The file is not owned by root"],2,"To reach a file a user needs execute (search) permission on every directory in the path; namei -l shows where it fails. umask only affects new files.","File systems: diagnose and correct file permission problems",["The sticky bit on a file has no effect on Linux, and it isn't needed to read a file.","umask only sets permissions for newly created files; it doesn't block reading an existing 644 file.",null,"Ownership by root isn't required; mode 644 already grants read to everyone who can reach the file."],null],["rh53",0,6,"After adding a line to /etc/fstab, how do you test it without rebooting?",["Run mount -a and check with findmnt","Run systemctl isolate local-fs.target now","Run partprobe then reboot","Run fsck -A on every disk"],0,"mount -a mounts every fstab entry that isn't already mounted, so errors appear now instead of at boot. findmnt --verify also checks the file.","File systems: mount and unmount file systems",[null,"Isolating local-fs.target stops units not required by that target, which can shut down services, and it's not the standard fstab test.","partprobe rereads partition tables, and rebooting is exactly the risk the test is meant to avoid.","fsck checks file system consistency; it doesn't test that fstab entries mount."],null],["rh54",0,6,"Which command formats /dev/vgdata/lvdocs with ext4 and the label DOCS?",["mkfs.ext4 -n DOCS /dev/vgdata/lvdocs","mkfs.ext4 -L DOCS /dev/vgdata/lvdocs","mkfs.xfs -L DOCS /dev/vgdata/lvdocs","e2label -c DOCS /dev/vgdata/lvdocs"],1,"mkfs.ext4 -L sets the label, which fstab can use as LABEL=DOCS. mkfs.xfs would create the wrong type.","File systems: create ext4 file systems",["For mkfs.ext4, -n is not the label option; -L sets the volume label.",null,"mkfs.xfs creates XFS, not ext4, even though -L would set a label.","e2label sets a label on an existing ext file system; it has no -c option and doesn't format the device."],null],["rh55",0,7,"A cleanup script must run at 02:30 every day through cron. Which crontab line is correct?",["2 30 * * * /usr/local/bin/cleanup.sh","30 2 * * * /usr/local/bin/cleanup.sh","30 2 1 * * /usr/local/bin/cleanup.sh","* 2 30 * * /usr/local/bin/cleanup.sh"],1,"Cron fields are minute, hour, day of month, month, day of week. 30 2 * * * is 02:30 daily; the third option runs only on the 1st.","Deploy and maintain: schedule tasks using cron",["Minute and hour are swapped: 2 30 means minute 2 of hour 30, which is invalid.",null,"The 1 in the day-of-month field makes it run only on the 1st of each month.","The * minute runs every minute of the 02 hour, and 30 is in the day-of-month field, so it runs on the 30th only."],null],["rh56",0,7,"You wrote report.service and report.timer with OnCalendar=Mon *-*-* 06:00:00. What makes the job run on schedule, including after reboots?",["systemctl enable --now report.service","systemctl start report.service","systemctl enable --now report.timer","crontab -e and add report.timer"],2,"The timer unit triggers the service, so enable and start the timer. Enabling the service would just run it at boot.","Deploy and maintain: schedule tasks using systemd timers",["Enabling the service ties it to boot, not to the schedule, so the timer never triggers it.","Starting the service runs it once now; nothing schedules future runs.",null,"crontab lines run commands, not systemd timer units; the timer has to be enabled in systemd."],null],["rh57",0,7,"Which command runs /root/fix.sh once, 20 minutes from now?",["echo /root/fix.sh | at now + 20 minutes","at -f /root/fix.sh daily","crontab -e 20m /root/fix.sh","systemd-run --on-calendar=+20"],0,"at runs a job once at a given time, reading commands from stdin. The cron-style options run on a repeating schedule or use invalid syntax.","Deploy and maintain: schedule tasks using at",[null,"at -f reads the job from a file, but 'daily' is not a valid at time, and at never repeats.","crontab -e opens an editor; it takes no time or script arguments and cron schedules repeat.","systemd-run --on-calendar needs a calendar expression; '+20' isn't valid there (--on-active=20m would be the relative form)."],null],["rh58",0,7,"httpd must start now and also start at every boot. Which command does both?",["systemctl start httpd --boot","systemctl unmask httpd","systemctl enable httpd","systemctl enable --now httpd"],3,"enable --now creates the boot-time symlinks and starts the service. enable alone only takes effect at the next boot.","Deploy and maintain: start and stop services and configure them to start at boot",["systemctl start has no --boot option; start alone runs it now but doesn't enable it at boot.","unmask removes a mask so the unit can be started; it neither starts nor enables httpd.","enable creates the boot-time symlinks, but httpd isn't started until the next boot.",null],null],["rh59",0,7,"A graphical server should boot to a text console by default. Which command sets this?",["systemctl isolate multi-user.target","systemctl set-default multi-user.target","systemctl enable rescue.target","grubby --set-default multi-user"],1,"set-default changes the default target used at boot. isolate switches targets now but doesn't change the default.","Deploy and maintain: configure systems to boot into a specific target",["isolate switches to multi-user.target right now but doesn't change the default for the next boot.",null,"Enabling rescue.target doesn't make it the default and rescue mode isn't a normal text console.","grubby sets the default kernel, not the systemd target, and 'multi-user' isn't a kernel."],null],["rh60",0,7,"A server must get its time from classroom.example.com. Which line in /etc/chrony.conf does this?",["ntpserver classroom.example.com prefer","server classroom.example.com iburst","pool = classroom.example.com","timeserver classroom.example.com"],1,"chrony uses server (or pool) followed by a host name; iburst speeds up the first sync. Restart chronyd and check with chronyc sources.","Deploy and maintain: configure time service clients",["ntpserver isn't a chrony directive, and prefer is ntpd syntax; chronyd would reject the line.",null,"chrony directives don't use '=', so 'pool =' is a syntax error; the correct form is 'pool host iburst'.","timeserver isn't a chrony.conf directive; chronyd ignores it or reports an error."],null],["rh61",0,7,"Which command adds the kernel argument audit=1 to every installed kernel's boot entry?",["grubby --update-kernel=ALL --args=\"audit=1\"","grub2-install --args=\"audit=1\"","dracut --add audit=1 --all","sysctl -w audit=1"],0,"grubby edits the boot entries directly. grub2-install installs the boot loader and dracut builds the initramfs.","Deploy and maintain: modify the system bootloader",[null,"grub2-install writes the boot loader to disk and has no --args option for kernel arguments.","dracut builds the initramfs image; it doesn't edit kernel command-line arguments in boot entries this way.","sysctl changes runtime kernel parameters under /proc/sys; audit=1 is a boot argument and there is no such sysctl."],null],["rh62",0,7,"You edited GRUB_TIMEOUT in /etc/default/grub on a BIOS system. What makes the change take effect?",["dracut -f","grub2-mkconfig -o /boot/grub2/grub.cfg","systemctl restart grub2","grubby --info=ALL"],1,"grub2-mkconfig regenerates grub.cfg from /etc/default/grub and the scripts in /etc/grub.d. grubby --info only displays entries.","Deploy and maintain: modify the system bootloader",["dracut -f rebuilds the initramfs, which doesn't contain GRUB settings like the menu timeout.",null,"GRUB isn't a service; there is no grub2 unit to restart, and it only reads grub.cfg at boot.","grubby --info=ALL only displays boot entries; it doesn't regenerate grub.cfg from /etc/default/grub."],null],["rh63",0,7,"A new RHEL 10 VM from the Developer subscription can't reach the Red Hat CDN repositories. What should you do first?",["Run subscription-manager register","Run dnf clean all","Enable EPEL","Set gpgcheck=0 and sslverify=0 in /etc/dnf/dnf.conf"],0,"The CDN repositories only work on a registered system; register with subscription-manager and your Red Hat account. Cleaning caches doesn't grant access.","Deploy and maintain: install and update packages from Red Hat CDN",[null,"dnf clean all removes cached metadata, but an unregistered system still has no entitlement to reach the CDN repos.","EPEL is a community repository of extra packages; it doesn't give access to Red Hat's BaseOS and AppStream content.","Turning off GPG and SSL checks weakens security and doesn't fix the missing registration the CDN requires."],null],["rh64",0,8,"Connection 'ens3' must use 10.0.0.20/24, gateway 10.0.0.1 and no DHCP. Which command sets this?",["nmcli con mod ens3 ipv4.addresses 10.0.0.20/24 ipv4.gateway 10.0.0.1 ipv4.method manual","nmcli dev set ens3 ip 10.0.0.20/24 gw 10.0.0.1","ip addr add 10.0.0.20/24 dev ens3 permanent","nmcli con mod ens3 ipv4.method auto ipv4.addresses 10.0.0.20/24"],0,"nmcli con mod changes the saved profile; ipv4.method manual turns off DHCP. ip addr add is lost at reboot, and method auto keeps DHCP.","Manage basic networking: configure IPv4 and IPv6 addresses",[null,"nmcli dev set changes device properties like autoconnect or managed; it has no ip or gw arguments.","ip addr add changes only the running interface, is lost at reboot, and has no 'permanent' keyword.","ipv4.method auto keeps DHCP enabled, and the gateway isn't set, so this doesn't meet the requirement."],null],["rh65",0,8,"You changed the IP settings of connection 'ens3' with nmcli con mod. How do you apply them now?",["systemctl restart network","nmcli general reload dns","ifup ens3 --reload","nmcli con up ens3"],3,"Reactivating the connection applies the changed profile. The legacy network service and ifup scripts are not part of RHEL 10.","Manage basic networking: configure IPv4 and IPv6 addresses",["RHEL 10 has no legacy network service; NetworkManager manages connections.","nmcli general reload dns only reapplies DNS settings, not the new IP address and gateway on ens3.","The ifup scripts aren't used on RHEL 10, and --reload isn't a valid ifup option.",null],null],["rh66",0,8,"Where does RHEL 10 store persistent NetworkManager connection profiles?",["/etc/sysconfig/network-scripts/ifcfg-*","/etc/network/interfaces","/etc/NetworkManager/system-connections/","/run/NetworkManager/devices/"],2,"RHEL 10 uses keyfiles (*.nmconnection) in /etc/NetworkManager/system-connections/. ifcfg files are no longer supported, and /etc/network/interfaces is a Debian file.","Manage basic networking: configure network settings",["ifcfg files in network-scripts were deprecated and are no longer supported on RHEL 10.","/etc/network/interfaces is the Debian/Ubuntu ifupdown file; RHEL never used it.",null,"/run is a temporary file system cleared at boot, so profiles there wouldn't be persistent."],null],["rh67",0,8,"Which command sets the persistent hostname to web1.example.com?",["hostname web1.example.com","echo web1.example.com >> /etc/sysconfig/network","nmcli con mod hostname web1.example.com","hostnamectl set-hostname web1.example.com"],3,"hostnamectl set-hostname writes /etc/hostname and applies the name immediately. The hostname command alone is lost at reboot.","Manage basic networking: configure hostname resolution",["The hostname command changes the name only in the running kernel, so it is lost at reboot.","Appending to /etc/sysconfig/network doesn't set the hostname on modern RHEL; the persistent name lives in /etc/hostname.","nmcli con mod needs a connection name and a property; 'hostname' isn't a valid connection, so the command fails.",null],null],["rh68",0,8,"Connection 'ens3' needs DNS server 10.0.0.53. Which method survives NetworkManager restarts?",["Edit /etc/resolv.conf directly","nmcli con mod ens3 ipv4.dns 10.0.0.53","Add 10.0.0.53 to /etc/hosts","hostnamectl set-dns 10.0.0.53"],1,"NetworkManager writes /etc/resolv.conf from the connection's ipv4.dns setting, so manual edits are overwritten. /etc/hosts maps names, not DNS servers.","Manage basic networking: configure hostname resolution",["NetworkManager regenerates /etc/resolv.conf, so manual edits are overwritten on restart or reconnect.",null,"/etc/hosts maps host names to addresses; it can't specify which DNS server to query.","hostnamectl manages the host name and has no set-dns subcommand."],null],["rh69",0,8,"The web server must be reachable on the http service after reboots. Which pair of commands is correct?",["firewall-cmd --add-service=http; firewall-cmd --runtime-to-reboot","firewall-cmd --permanent --add-port=http; systemctl restart httpd","firewall-cmd --permanent --add-service=http; firewall-cmd --reload","firewall-cmd --add-service=http --zone=trusted --save"],2,"--permanent saves the rule and --reload loads it into the running firewall. Without --permanent the rule is lost at reload or reboot.","Manage basic networking: restrict network access using firewall-cmd",["A rule without --permanent is lost at reload or reboot, and --runtime-to-reboot isn't a real option (the real one is --runtime-to-permanent).","--add-port needs a port/protocol like 80/tcp, not a service name, and restarting httpd doesn't load firewall rules.",null,"firewall-cmd has no --save option, and the trusted zone isn't where the server's interface usually is."],null],["rh70",0,8,"Which command shows which TCP ports are listening and which processes own them?",["ss -tlnp","ip route show","nmcli dev status","ping -c1 localhost"],0,"ss -tlnp lists TCP listening sockets with numeric ports and process names. ip route shows routes, not sockets.","Manage basic networking: configure network services to start at boot",[null,"ip route show prints the routing table, not listening sockets or processes.","nmcli dev status shows each network device's state and connection, not open ports.","ping only tests reachability with ICMP; it tells you nothing about listening TCP ports."],null],["rh71",0,9,"Create user svcbackup with UID 1500 and no interactive login. Which command does this?",["useradd -u 1500 -s /sbin/nologin svcbackup","useradd -g 1500 -s /bin/false svcbackup","usermod -u 1500 -L svcbackup","useradd -U 1500 -d /dev/null svcbackup"],0,"-u sets the UID and -s /sbin/nologin blocks interactive logins. -g sets the primary group, and usermod changes an existing user.","Users and groups: create, delete and modify local user accounts",[null,"-g sets the primary group (which must already exist), not the UID, so the user gets an automatic UID.","usermod changes an existing account, and -L locks the password; it doesn't create the user or set a nologin shell.","-U creates a same-named group and takes no value, and a /dev/null home directory doesn't block interactive login."],null],["rh72",0,9,"User alice must be added to group developers without losing her other supplementary groups. Which command is right?",["usermod -G developers alice","useradd -G developers alice","groupmod -a alice developers","usermod -aG developers alice"],3,"-a with -G appends. -G alone replaces all supplementary groups, and useradd creates new users.","Users and groups: modify group membership",["-G without -a replaces all of alice's supplementary groups, so she loses her other memberships.","useradd creates new accounts; it fails because alice already exists.","groupmod changes a group's name or GID; it has no -a option for adding members (gpasswd -a would).",null],null],["rh73",0,9,"Which command makes user bob choose a new password the next time he logs in?",["chage -d 0 bob","chage -M 0 bob","passwd -l bob","usermod -e 0 bob"],0,"Setting the last change date to 0 forces a change at next login. -M 0 sets a zero-day maximum age, and passwd -l locks the account.","Users and groups: change passwords and adjust password aging",[null,"-M 0 sets the maximum password age to 0 days, a permanent policy change that makes the password expire immediately after every change.","passwd -l locks the password, so bob can't log in with it at all, never mind change it.","usermod -e 0 sets the account expiry date to 1 January 1970, so the account is expired and can't log in."],null],["rh74",0,9,"New accounts must default to a 60-day maximum password age. Which file should you edit?",["/etc/default/useradd","/etc/security/pwquality.conf","/etc/login.defs","/etc/shadow"],2,"PASS_MAX_DAYS in /etc/login.defs sets the default for new accounts. Editing /etc/shadow changes existing users only, and pwquality controls password complexity.","Users and groups: change passwords and adjust password aging",["/etc/default/useradd holds defaults like home base, shell and skel, not password aging.","pwquality.conf controls password complexity (length, character classes), not maximum age.",null,"Editing /etc/shadow changes existing accounts only; new accounts get defaults from /etc/login.defs."],null],["rh75",0,9,"Create group finance with GID 4000. Which command is correct?",["groupadd -u 4000 finance","groupmod -g 4000 finance","addgroup finance 4000","groupadd -g 4000 finance"],3,"groupadd -g sets the GID when creating a group. groupmod changes an existing group, and addgroup is not a RHEL command.","Users and groups: create, delete and modify local groups",["groupadd has no -u option; the GID is set with -g.","groupmod changes a group that already exists, so it fails if finance hasn't been created.","addgroup is a Debian-style helper that isn't part of RHEL.",null],null],["rh76",0,9,"Members of group admins must run any command as root through sudo. Which drop-in line is correct?",["admins ALL=(ALL) ALL","%admins ALL=(ALL) ALL","@admins ALL=(ALL) ALL","group:admins ALL=ALL"],1,"In sudoers a % prefix marks a group. Without it, sudo treats admins as a user name.","Users and groups: configure superuser access",["Without %, sudoers treats admins as a user name, so group members get nothing.",null,"@ marks a netgroup in sudoers, not a local group.","group: isn't valid sudoers syntax, and the run-as part should be (ALL)."],null],["rh77",0,9,"Which command removes user olduser along with the home directory and mail spool?",["userdel -f olduser","usermod -L olduser","userdel -r olduser","deluser --home olduser"],2,"userdel -r deletes the account, home directory and mail spool. -f forces removal even while logged in, and usermod -L only locks the account.","Users and groups: create, delete and modify local user accounts",["-f forces removal even while the user is logged in, but without -r the home directory and mail spool stay.","usermod -L only locks the password; the account and home directory still exist.",null,"deluser is a Debian tool that isn't on RHEL, and --home isn't how it removes home directories."],null],["rh78",0,10,"httpd must serve files from /srv/web with SELinux enforcing. Which commands set the right context in a way that survives a relabel?",["chcon -R -t httpd_sys_content_t /srv/web","setsebool -P httpd_read_srv on","semanage fcontext -a -t httpd_sys_content_t \"/srv/web(/.*)?\"; restorecon -Rv /srv/web","chmod -R 755 /srv/web; restorecon -Rv /srv/web"],2,"semanage fcontext adds a lasting rule and restorecon applies it. chcon changes labels only until the next relabel or restorecon.","Manage security: restore default file contexts",["chcon sets the label directly, but a relabel or restorecon puts back the policy default, undoing it.","There is no httpd_read_srv boolean, and booleans don't change file labels.",null,"chmod changes standard permissions, and without a new fcontext rule restorecon only reapplies the existing default labels."],null],["rh79",0,10,"Which command shows the SELinux context of files in /var/www/html?",["ls -Z /var/www/html","getsebool /var/www/html","sestatus /var/www/html","id -Z /var/www/html"],0,"ls -Z adds the SELinux context to the listing. id -Z shows your own context and sestatus the overall SELinux state.","Manage security: list and identify SELinux file and process context",[null,"getsebool shows SELinux boolean values and doesn't take a directory argument.","sestatus reports the overall SELinux state and policy, not individual file contexts.","id -Z shows the context of your own login session, not files."],null],["rh80",0,10,"httpd is set to listen on TCP 8090 but fails to start with SELinux enforcing. Which command fixes the SELinux side?",["setsebool -P httpd_can_network_connect on","semanage port -a -t http_port_t -p tcp 8090","firewall-cmd --permanent --add-port=8090/tcp","restorecon -Rv /etc/httpd"],1,"The port needs the http_port_t label before httpd_t may bind to it. The boolean controls outgoing connections, and the firewall rule affects clients, not whether httpd starts.","Manage security: manage SELinux port labels",["httpd_can_network_connect allows outgoing connections from httpd; it doesn't let httpd bind to an unlabeled port.",null,"The firewall affects whether clients can reach the port, but SELinux still blocks httpd from binding, so it won't start.","restorecon resets file labels under /etc/httpd; the problem is the port label, not file contexts."],null],["rh81",0,10,"Web apps need to connect to a remote database. Which command allows this permanently?",["setsebool -P httpd_can_network_connect_db on","setsebool httpd_can_network_connect_db on","semanage port -a -t db_port_t 3306","setenforce 0"],0,"setsebool -P saves the boolean so it survives reboots. Without -P it resets at boot, and setenforce 0 disables protection for everything.","Manage security: use boolean settings to modify SELinux settings",[null,"Without -P the boolean change is lost at the next reboot, so it's not permanent.","There is no db_port_t type, 3306 is already labeled mysqld_port_t, and the command lacks -p tcp; port labels don't grant httpd permission to connect.","setenforce 0 switches the whole system to permissive, removing protection instead of allowing only this access."],null],["rh82",0,10,"Which command searches the audit log for recent SELinux denials?",["journalctl -u selinux","ausearch -m AVC -ts recent","getenforce -v","grep -i avc /var/log/secure /var/log/boot.log"],1,"SELinux denials are AVC records in /var/log/audit/audit.log, and ausearch -m AVC filters them. They don't appear in /var/log/secure.","Manage security: diagnose and address routine SELinux policy violations",["SELinux isn't a systemd unit, so journalctl -u selinux shows nothing useful.",null,"getenforce only prints the current mode and doesn't take -v or search logs.","AVC denials are recorded by auditd in audit.log, not in /var/log/secure or boot.log."],null],["rh83",0,10,"SELinux must stay enforcing after reboot. It is currently permissive. What do you do?",["setenforce 1 only","Set SELINUX=enforcing in /etc/selinux/config and run setenforce 1","Set SELINUXTYPE=enforcing and reboot","Run semanage enforce -P on"],1,"setenforce changes the mode now; /etc/selinux/config sets the mode at boot. SELINUXTYPE picks the policy (targeted), not the mode.","Manage security: set enforcing and permissive modes for SELinux",["setenforce 1 only changes the running mode; the config file still says permissive, so it reverts at reboot.",null,"SELINUXTYPE picks the policy (such as targeted); 'enforcing' isn't a valid policy type.","semanage has no enforce subcommand; the boot mode is set in /etc/selinux/config."],null],["rh84",0,10,"While troubleshooting you want SELinux to log denials but not block anything, only until the next reboot. Which command fits?",["setenforce 0","setsebool -P permissive on","getenforce 0","semanage permissive -a all"],0,"setenforce 0 switches to permissive mode until reboot. The others use invalid options or change settings permanently.","Manage security: set enforcing and permissive modes for SELinux",[null,"There is no global 'permissive' boolean, and -P would make the change persist past reboot.","getenforce only reports the mode; it doesn't take an argument or change anything.","semanage permissive -a makes one domain permissive persistently; 'all' isn't a domain, and the change survives reboot."],null],["rh85",0,10,"A user's umask is 0027. What permissions does a new directory they create get?",["rwxr-xr-x (755)","rw-r----- (640)","rwxr-x--- (750)","rwxrwx--- (770)"],2,"Directories start from 777; removing 027 leaves 750. New files start from 666 and would be 640.","Manage security: manage default file permissions",["755 would come from umask 022; 027 also removes read and execute for others.","640 is what a new file gets with umask 027; directories start from 777 so they keep execute.",null,"770 would need umask 007; 027 also removes group write."],null],["rh86",0,10,"User deploy needs password-free SSH to server2. After running ssh-keygen, which command installs the public key on server2?",["scp ~/.ssh/id_ed25519 server2:~/.ssh/","ssh-copy-id deploy@server2","ssh-add deploy@server2","ssh-keyscan server2 >> ~/.ssh/authorized_keys"],1,"ssh-copy-id appends your public key to ~/.ssh/authorized_keys on the remote host and fixes permissions. Copying the private key is unsafe, and ssh-keyscan collects host keys.","Manage security: configure key-based authentication for SSH",["This copies the private key to the server, which is unsafe and doesn't add anything to authorized_keys.",null,"ssh-add loads a private key into the local ssh-agent; it doesn't install anything on server2.","ssh-keyscan collects the server's host keys, which belong in known_hosts, not your authorized_keys."],null],["rh87",0,10,"Key login fails and the sshd log mentions bad ownership or modes for authorized_keys. Which permissions should you set?",["~/.ssh 755 and authorized_keys 644","~/.ssh 777 and authorized_keys 666","~/.ssh 700 and authorized_keys 600","~/.ssh 711 and authorized_keys 755"],2,"With StrictModes on, sshd refuses keys if others can write to ~/.ssh or authorized_keys. 700 and 600 owned by the user are the safe values.","Manage security: configure key-based authentication for SSH",["sshd with StrictModes only rejects group- or world-writable files, so 755/644 can work, but it is looser than needed; 700 and 600 is the expected secure setting.","777 and 666 let anyone write to them, which is exactly what makes sshd with StrictModes refuse the key.",null,"authorized_keys doesn't need execute bits, and 711/755 are looser than needed; 700 and 600 are what sshd expects."],null],["rh88",0,10,"After allowing key logins, the admin wants to block password logins over SSH. Which sshd_config setting does this?",["PubkeyAuthentication no","PermitRootLogin prohibit-password","UsePAM no","PasswordAuthentication no"],3,"PasswordAuthentication no disables password logins for all users; then reload sshd. prohibit-password only affects root.","Manage security: configure key-based authentication for SSH",["PubkeyAuthentication no disables key logins, the opposite of what's wanted, and passwords still work.","prohibit-password only affects root logins; other users can still log in with passwords.","UsePAM no changes how sshd uses PAM and isn't supported on RHEL; it doesn't cleanly disable password logins.",null],null],["rh89",0,10,"Only hosts in 192.168.50.0/24 should reach services in the internal zone. Which command sends that network's traffic to the internal zone permanently?",["firewall-cmd --permanent --zone=internal --add-source=192.168.50.0/24","firewall-cmd --permanent --zone=internal --add-interface=192.168.50.0/24","firewall-cmd --zone=internal --add-port=192.168.50.0/24","firewall-cmd --set-default-zone=192.168.50.0/24"],0,"--add-source binds a network to a zone, so its traffic uses that zone's rules. --add-interface takes an interface name, not a network, and default-zone takes a zone name.","Manage security: configure firewall settings using firewall-cmd",[null,"--add-interface expects an interface name like ens3, not a network address.","--add-port expects a port/protocol like 8080/tcp, and without --permanent it isn't persistent.","--set-default-zone takes a zone name, not a network, and doesn't bind sources to a zone."],null],["rh90",0,10,"Which command shows the SELinux context of the running httpd processes?",["ls -Z /usr/sbin/httpd","ps -eZ | grep httpd","getsebool -a | grep httpd","seinfo -p httpd"],1,"ps -eZ adds the process context, such as httpd_t. ls -Z shows the executable file's label, not the process.","Manage security: list and identify SELinux process context",["ls -Z shows the label of the httpd binary on disk (httpd_exec_t), not the running processes' domain.",null,"getsebool -a lists boolean values, not the context of running processes.","seinfo queries the policy (types, roles, and so on); -p isn't a way to show running processes."],null]]);
